    /// <li>
    /// <p><code>INITIALIZING</code> – ONTAP is setting up the SVM peer relationship.</p></li>
    /// <li>
    /// <p><code>SUSPENDED</code> – The SVM peer relationship is suspended.</p></li>
    /// <li>
    /// <p><code>REJECTED</code> – The peering request was rejected.</p></li>
